const contentAudit = qualityCounts(FLASHCARD_DATABASE);

// 閃卡互動內部狀態
let currentTier = 'elem_1000';
let currentCardIndex = 0;
let isFlipped = false;
let justFlipped = false;
let autoPlayToken = 0;
let autoPlayStepTimer = null;
let isAutoPlaying = false;
let audioFailure = '';
let autoPlayVoiceMode = 'word_zh_sentence'; // 'word_zh_sentence' | 'word_zh' | 'word_sentence' | 'word_en_thinking'
let practiceBatchSize = 20; // 10 | 20 | 30 | 50 | 100 | 0 (0 為全部)
let currentBatchIndex = 0;
let batchCompleted = false;
let cardFilterStatus = 'all'; // 'all' | 'need_review' | 'mastered'
let cardSetType = 'all'; // 'all' | 'phrases'
let cardSearchKeyword = '';
let currentCardQuizChoice = null; // { cardId, pickIndex }

// 本機學習進度 (cardId -> 'mastered' | 'need_review')
const STORAGE_KEY = 'eq_flashcards_mastery_v1';
let masteryState = {};
try {
  const saved = localStorage.getItem(STORAGE_KEY);
  if (saved) masteryState = JSON.parse(saved);
} catch (e) {
  masteryState = {};
}

function saveMastery() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(masteryState));
  } catch (e) {}
}

function isPhraseOrCollocationCard(c) {
  return c.word.includes(' ') || c.word.includes('-') || /片語|搭配|慣用/.test(c.category || '') || (c.collocation && c.collocation.trim().split(/\s+/).length >= 2);
}

function buildEnglishThinkingClue(card) {
  if (!card) return '';
  const word = String(card.word || '').trim();
  const example = String(card.example || '').trim();
  if (example && word) {
    const escaped = word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const masked = example.replace(new RegExp(escaped, 'gi'), '[ _____ ]');
    if (masked !== example) return masked;
  }
  const coll = String(card.collocation || '').replace(/\s*\([^)]*\)/g, '').trim();
  if (coll) return `Collocation frame: "${coll}"`;
  return `Think in English: How would you use "${word}" (${card.pos || 'word'}) in a real sentence?`;
}

// 取得當前篩選後的卡片清單
function getFilteredCards() {
  let list = FLASHCARD_DATABASE.filter(c => c.tier === currentTier);

  if (cardSetType === 'phrases') {
    const phraseList = list.filter(isPhraseOrCollocationCard);
    if (phraseList.length > 0) list = phraseList;
  }

  if (cardSearchKeyword) {
    const kw = cardSearchKeyword.toLowerCase();
    list = list.filter(c => c.word.toLowerCase().includes(kw) || c.zh.includes(kw) || c.category.toLowerCase().includes(kw) || (c.collocation || '').toLowerCase().includes(kw));
  }

  if (cardFilterStatus === 'mastered') {
    list = list.filter(c => masteryState[c.id] === 'mastered');
  } else if (cardFilterStatus === 'need_review') {
    list = list.filter(c => masteryState[c.id] === 'need_review');
  }

  return list;
}

// 計算當前分類下的總組數
function getTotalBatches() {
  const filtered = getFilteredCards();
  return practiceBatchSize > 0 ? Math.max(1, Math.ceil(filtered.length / practiceBatchSize)) : 1;
}

// 取得當前分組的卡片清單
function getBatchCards() {
  const filtered = getFilteredCards();
  const total = getTotalBatches();
  if (currentBatchIndex >= total) {
    currentBatchIndex = Math.max(0, total - 1);
  }
  if (currentBatchIndex < 0) {
    currentBatchIndex = 0;
  }
  return practiceBatchSize > 0
    ? filtered.slice(currentBatchIndex * practiceBatchSize, (currentBatchIndex + 1) * practiceBatchSize)
    : filtered;
}

// 閃卡館主頁渲染函數
const quickTierLabels = { elem_1000: '國小', jhs_2000: '國中', shs_3000: '高中', toeic: 'TOEIC 多益', toefl: 'TOEFL 托福', sat: 'SAT', gre: 'GRE', gmat: 'GMAT' };
const quickMp3GroupIds = { elem_1000: 'elementary-001', jhs_2000: 'junior-001', shs_3000: 'senior-001', toeic: 'toeic-001', toefl: 'toefl-001', sat: 'sat-001', gre: 'gre-001', gmat: 'gmat-001' };
export function flashcardShortcut(key, render) {
  if (recallActive(currentTier)) {
    return recallShortcut(key, FLASHCARD_DATABASE.filter(c => c.tier === currentTier), render);
  }
  const activeInput = globalThis.document?.activeElement;
  if (activeInput && ['input', 'textarea', 'select'].includes(activeInput.tagName?.toLowerCase())) return false;
  const batchCards = getBatchCards();
  if (!batchCards.length) return false;
  if (key === ' ' || key === 'Enter') {
    isFlipped = !isFlipped;
    render();
    return true;
  }
  if (key === 'ArrowRight' || key === 'n' || key === 'N') {
    if (currentCardIndex < batchCards.length - 1) {
      currentCardIndex++;
      isFlipped = false;
      render();
      return true;
    }
  }
  if (key === 'ArrowLeft' || key === 'p' || key === 'P') {
    if (currentCardIndex > 0) {
      currentCardIndex--;
      isFlipped = false;
      render();
      return true;
    }
  }
  if (key === 's' || key === 'S') {
    const card = batchCards[currentCardIndex];
    if (card) {
      playWord(card.word, false);
      return true;
    }
  }
  if (['1', '2', '3', '4'].includes(key)) {
    const card = batchCards[currentCardIndex];
    if (card) {
      currentCardQuizChoice = { cardId: card.id, pickIndex: Number(key) - 1 };
      render();
      return true;
    }
  }
  return false;
}
export function renderFlashcardQuickPlay() {
  return `<section class="card flashcard-quick-play" aria-labelledby="flashcard-quick-title">
    <div class="pill">📱 手機直式單手快選 · 單字集 / 片語集一鍵即播</div>
    <h2 id="flashcard-quick-title">9,500 張閃卡與片語集，點選就開始聽讀</h2>
    <p>針對手機直式單手操作優化：點選下方任一<strong>分級單字集</strong>或<strong>高頻片語搭配集</strong>，立即啟動語音連播（每組 20 張，支援思考式純英與雙語模式）。</p>
    <div class="flashcard-quick-grid">${FLASHCARD_TIERS.map(t => `<button class="btn" data-fc-quick-play="${t.id}" aria-label="自動播放${quickTierLabels[t.id]}閃卡"><strong>▶ ${quickTierLabels[t.id]}</strong><span>${FLASHCARD_DATABASE.filter(c => c.tier === t.id).length.toLocaleString('en-US')} 張</span></button>`).join('')}</div>
    <div class="quick-phrase-sets" role="group" aria-label="高頻片語與英英思考語音集快選">
      <span class="quick-phrase-label">🔗 片語與搭配詞集即點即播：</span>
      <button class="btn quiet small" data-fc-phrase-play="shs_3000">▶ 高中核心動詞片語集</button>
      <button class="btn quiet small" data-fc-phrase-play="toeic">▶ TOEIC 商務片語搭配集</button>
      <button class="btn quiet small" data-fc-phrase-play="toefl">▶ TOEFL 學術轉折片語集</button>
      <button class="btn quiet small" data-fc-phrase-play="sat">▶ SAT 語境邏輯搭配集</button>
      <button class="btn quiet small" data-fc-phrase-play="gre">▶ GRE 雙選等價片語集</button>
      <button class="btn quiet small" data-fc-phrase-play="gmat">▶ GMAT 商業論證搭配集</button>
    </div>
    ${renderCommuteQuickPlayStrip()}
    <div class="learning-actions" style="margin-top:12px;margin-bottom:0">
      <button class="btn quiet" data-nav="flashcards">搜尋字卡與自訂複習</button>
      <a class="btn quiet" href="#listening">🎧 112 組通勤教學會話電台</a>
      <a class="btn quiet" href="#wordaudio/elementary-001">🎵 190 組 MP3 離線音檔</a>
      <a class="btn primary" href="EN/">🇬🇧 EN 純英檢定教學與英英語音 (TOEFL/TOEIC/SAT/GMAT/GRE) ↗</a>
    </div>
  </section>`;
}
export function startFlashcardQuickPlay(tier, renderCallback, phraseOnly = false) {
  if (!FLASHCARD_TIERS.some(t => t.id === tier)) return false;
  stopFlashcardAutoPlay();
  currentTier = tier;
  cardSearchKeyword = '';
  cardFilterStatus = 'all';
  cardSetType = phraseOnly ? 'phrases' : 'all';
  currentBatchIndex = 0;
  currentCardIndex = 0;
  practiceBatchSize = 20;
  autoPlayVoiceMode = 'word_zh_sentence';
  isFlipped = false;
  batchCompleted = false;
  startFlashcardAutoPlay(renderCallback);
  return true;
}

export function renderFlashcardsStudioView() {
  const tierInfo = FLASHCARD_TIERS.find(t => t.id === currentTier) || FLASHCARD_TIERS[0];
  const allTierCards = FLASHCARD_DATABASE.filter(c => c.tier === currentTier);
  const filteredCards = getFilteredCards();
  const totalBatches = getTotalBatches();
  const batchCards = getBatchCards();
  if (currentCardIndex >= batchCards.length) currentCardIndex = Math.max(0, batchCards.length - 1);
  const card = batchCards[currentCardIndex] ? teachingCard(batchCards[currentCardIndex]) : null;
  const mastered = allTierCards.filter(c => masteryState[c.id] === 'mastered').length;
  const justFlippedNow = justFlipped;
  justFlipped = false;
  return `<div class="flashcard-studio fcx">${renderRecallStudio(allTierCards, FLASHCARD_TIERS)}<div ${recallActive(currentTier) ? 'hidden' : ''}>${renderBrowse({
    esc, tierInfo, tierList: FLASHCARD_TIERS, allTierCards, filteredCards, totalBatches, batchCards, card,
    isMastered: card ? masteryState[card.id] === 'mastered' : false,
    isNeedReview: card ? masteryState[card.id] === 'need_review' : false,
    mastered, percent: allTierCards.length ? Math.round(mastered / allTierCards.length * 100) : 0,
    clue: buildEnglishThinkingClue(card), cardIndex: currentCardIndex, batchIndex: currentBatchIndex, batchSize: practiceBatchSize,
    flipped: isFlipped, justFlipped: justFlippedNow, autoPlaying: isAutoPlaying, voiceMode: autoPlayVoiceMode, audioFailure, batchCompleted,
    filterStatus: cardFilterStatus, setType: cardSetType, keyword: cardSearchKeyword,
    audit: `${contentAudit.total} 張字卡；例句與搭配詞由 AI 撰寫並經規則校驗，尚未經人類教師審核。發現錯誤歡迎回報。`,
    phraseCount: allTierCards.filter(isPhraseOrCollocationCard).length,
    reviewCount: allTierCards.filter(c => masteryState[c.id] === 'need_review').length,
    mp3Group: quickMp3GroupIds[currentTier] || 'elementary-001',
    quizChoice: currentCardQuizChoice
  })}</div></div>`;
}

// 閃卡事件處理
export function handleFlashcardEvents(target, renderCallback) {
  const d = target.dataset;
  if (d.fcRecall) {
    stopFlashcardAutoPlay();
    handleRecallAction(d.fcRecall, FLASHCARD_DATABASE.filter(c=>c.tier===currentTier), renderCallback);
    return true;
  }

  // 隨堂 4 選 1 快測選項
  if (d.fcQuizPick !== undefined) {
    if (isAutoPlaying) stopFlashcardAutoPlay();
    const batchCards = getBatchCards();
    const card = batchCards[currentCardIndex];
    if (card) {
      currentCardQuizChoice = { cardId: card.id, pickIndex: Number(d.fcQuizPick) };
      playWord(card.word, false);
      renderCallback();
    }
    return true;
  }

  // 重設本卡隨堂快測
  if (d.fcQuizReset) {
    currentCardQuizChoice = null;
    renderCallback();
    return true;
  }

  // SRS 記憶評分按鈕 (again / good / easy)
  if (d.fcRate) {
    if (isAutoPlaying) stopFlashcardAutoPlay();
    const batchCards = getBatchCards();
    const card = batchCards[currentCardIndex];
    if (card) {
      const advance = applyRate(d.fcRate, card, masteryState);
      saveMastery();
      currentCardQuizChoice = null;
      if (advance && currentCardIndex < batchCards.length - 1) {
        currentCardIndex++;
        isFlipped = false;
      }
      renderCallback();
    }
    return true;
  }

  // 切換級別
  if (d.fcTier) {
    currentTier = d.fcTier;
    currentBatchIndex = 0;
    currentCardIndex = 0;
    batchCompleted = false;
    isFlipped = false;
    stopFlashcardAutoPlay();
    renderCallback();
    return true;
  }

  // 切換單字集 / 片語與搭配集
  if (d.fcSetType) {
    if (['all', 'phrases'].includes(d.fcSetType)) {
      cardSetType = d.fcSetType;
      currentBatchIndex = 0;
      currentCardIndex = 0;
      batchCompleted = false;
      isFlipped = false;
      stopFlashcardAutoPlay();
      renderCallback();
    }
    return true;
  }

  // 變更每批次練習字數 (10, 20, 30, 50, 100, 0: 全部)
  if (d.fcBatchSize !== undefined) {
    if(!['10','20','30','50','100','0'].includes(String(d.fcBatchSize))) return true;
    practiceBatchSize = Number(d.fcBatchSize);
    currentBatchIndex = 0;
    currentCardIndex = 0;
    batchCompleted = false;
    isFlipped = false;
    stopFlashcardAutoPlay();
    renderCallback();
    return true;
  }

  // 變更輪播語音模式
  if (d.fcVoiceMode) {
    if(!['word_zh_sentence','word_zh','word_sentence','word_en_thinking'].includes(d.fcVoiceMode)) return true;
    stopFlashcardAutoPlay();
    audioFailure = '';
    autoPlayVoiceMode = d.fcVoiceMode;
    renderCallback();
    return true;
  }

  // 分組切換：上一組
  if (d.fcBatchPrev) {
    if (currentBatchIndex > 0) {
      currentBatchIndex--;
      currentCardIndex = 0;
      batchCompleted = false;
      isFlipped = false;
      stopFlashcardAutoPlay();
      renderCallback();
    }
    return true;
  }

  // 分組切換：下一組
  if (d.fcBatchNext) {
    const totalBatches = getTotalBatches();
    if (currentBatchIndex < totalBatches - 1) {
      currentBatchIndex++;
      currentCardIndex = 0;
      batchCompleted = false;
      isFlipped = false;
      stopFlashcardAutoPlay();
      renderCallback();
    }
    return true;
  }

  // 重新輪播當前組
  if (d.fcReplayBatch) {
    currentCardIndex = 0;
    batchCompleted = false;
    isFlipped = false;
    startFlashcardAutoPlay(renderCallback);
    renderCallback();
    return true;
  }

  // 從第 1 組重新開始輪播
  if (d.fcRestartFirstBatch) {
    currentBatchIndex = 0;
    currentCardIndex = 0;
    batchCompleted = false;
    isFlipped = false;
    startFlashcardAutoPlay(renderCallback);
    renderCallback();
    return true;
  }

  // 翻轉卡片
  if (d.fcFlip) {
    if (isAutoPlaying) stopFlashcardAutoPlay();
    else stopAudio();
    isFlipped = !isFlipped;
    renderCallback();
    return true;
  }

  // 發音單字 (標準 1.0x)
  if (d.fcSpeakWord) {
    if (isAutoPlaying) { stopFlashcardAutoPlay(); renderCallback(); }
    playWord(d.fcSpeakWord, false);
    return true;
  }

  // 慢速發音單字 (0.65x)
  if (d.fcSpeakWordSlow) {
    if (isAutoPlaying) { stopFlashcardAutoPlay(); renderCallback(); }
    playWord(d.fcSpeakWordSlow, true);
    return true;
  }

  // 發音繁中釋義
  if (d.fcSpeakZh) {
    if (isAutoPlaying) { stopFlashcardAutoPlay(); renderCallback(); }
    playChinese(d.fcSpeakZh);
    return true;
  }

  // 發音例句 (標準)
  if (d.fcSpeakSentence) {
    if (isAutoPlaying) { stopFlashcardAutoPlay(); renderCallback(); }
    playSentence(d.fcSpeakSentence, false);
    return true;
  }

  // 慢速發音例句 (0.75x)
  if (d.fcSpeakSentenceSlow) {
    if (isAutoPlaying) { stopFlashcardAutoPlay(); renderCallback(); }
    playSentence(d.fcSpeakSentenceSlow, true);
    return true;
  }

  // 上一張卡片
  if (d.fcPrev) {
    if (isAutoPlaying) stopFlashcardAutoPlay();
    else stopAudio();
    if (currentCardIndex > 0) {
      currentCardIndex--;
      isFlipped = false;
      renderCallback();
    }
    return true;
  }

  // 下一張卡片
  if (d.fcNext) {
    if (isAutoPlaying) stopFlashcardAutoPlay();
    else stopAudio();
    const batchCards = getBatchCards();
    if (currentCardIndex < batchCards.length - 1) {
      currentCardIndex++;
      isFlipped = false;
      renderCallback();
    }
    return true;
  }

  // 標記掌握狀態
  if (d.fcMark) {
    const batchCards = getBatchCards();
    const card = batchCards[currentCardIndex];
    if (card) {
      if (masteryState[card.id] === d.fcMark) {
        delete masteryState[card.id];
      } else {
        masteryState[card.id] = d.fcMark;
      }
      saveMastery();
      renderCallback();
    }
    return true;
  }

  // 切換卡片篩選 (all, need_review, mastered)
  if (d.fcFilter) {
    cardFilterStatus = d.fcFilter;
    currentBatchIndex = 0;
    currentCardIndex = 0;
    batchCompleted = false;
    isFlipped = false;
    stopFlashcardAutoPlay();
    renderCallback();
    return true;
  }

  // 洗牌隨機重排
  if (d.fcShuffle) {
    if (isAutoPlaying) stopFlashcardAutoPlay();
    else stopAudio();
    const batchCards = getBatchCards();
    if (batchCards.length > 1) {
      currentCardIndex = Math.floor(Math.random() * batchCards.length);
      isFlipped = false;
      renderCallback();
    }
    return true;
  }

  // 切換自動輪播
  if (d.fcToggleAutoplay) {
    if (isAutoPlaying) {
      stopFlashcardAutoPlay();
    } else {
      startFlashcardAutoPlay(renderCallback);
    }
    renderCallback();
    return true;
  }

  return false;
}

// 停止自動輪播聽讀
export function stopFlashcardAutoPlay() {
  autoPlayToken++;
  if (autoPlayStepTimer) {
    clearTimeout(autoPlayStepTimer);
    autoPlayStepTimer = null;
  }
  isAutoPlaying = false;
  stopAudio();
}

// 啟動自動輪播聽讀（依序列：英文單字 ➔ 翻面 ➔ 繁中釋義 ➔ [可選英文例句] ➔ 自動下一張）
export function startFlashcardAutoPlay(renderCallback) {
  stopFlashcardAutoPlay();
  isAutoPlaying = true;
  audioFailure = '';
  currentCardIndex = 0;
  batchCompleted = false;
  const currentToken = ++autoPlayToken;

  function failAudio() {
    if(!isAutoPlaying || autoPlayToken !== currentToken) return;
    stopFlashcardAutoPlay();
    audioFailure='語音未完整播放，已停在本張。請確認裝置的英文／中文語音可用，再按啟動從本組第一張重播；不會略過未播完的內容。';
    renderCallback();
  }

  function runCurrentCard() {
    if (!isAutoPlaying || autoPlayToken !== currentToken) return;

    const batchCards = getBatchCards();
    if (!batchCards.length || currentCardIndex >= batchCards.length) {
      stopFlashcardAutoPlay();
      renderCallback();
      return;
    }

    const card = teachingCard(batchCards[currentCardIndex]);

    // 階段 1：卡片顯示正面純英文，完整朗讀英文單字
    isFlipped = false;
    renderCallback();

    playWord(card.word, false, {
      onEnd: () => {
        if (!isAutoPlaying || autoPlayToken !== currentToken) return;

        // 英文單字結束後停頓（思考式純英模式給予 1100ms 語境推理時間，一般模式 600ms）
        const thinkDelay = autoPlayVoiceMode === 'word_en_thinking' ? 1100 : 600;
        autoPlayStepTimer = setTimeout(() => {
          if (!isAutoPlaying || autoPlayToken !== currentToken) return;

          // 階段 2：翻至背面顯示核心釋義與主題圖示
          isFlipped = true;
          renderCallback();

          if (autoPlayVoiceMode === 'word_sentence' || autoPlayVoiceMode === 'word_en_thinking') {
            // 純英例句 / 思考式純英模式：不朗讀中文，直接朗讀英文搭配與完整英文例句
            const enCollocation = String(card.collocation || '').replace(/\s*\([^)]*\)/g, '').trim();
            if (autoPlayVoiceMode === 'word_en_thinking' && enCollocation && enCollocation.toLowerCase() !== card.word.toLowerCase()) {
              playSentence(enCollocation, false, {
                onEnd: () => {
                  if (!isAutoPlaying || autoPlayToken !== currentToken) return;
                  playSentenceStep();
                },
                onError: failAudio
              });
            } else {
              playSentenceStep();
            }
          } else if (autoPlayVoiceMode === 'word_zh') {
            // 簡易快速複習模式：僅朗讀英文單字 + 繁中釋義（無例句，快速高效複習）
            playChinese(card.zh, {
              onEnd: () => {
                if (!isAutoPlaying || autoPlayToken !== currentToken) return;
                proceedToNextCard(800);
              },
              onError: failAudio
            });
          } else {
            // 完整聽讀標準模式 (word_zh_sentence)：英文單字 ➔ 中文釋義 ➔ 完整例句英文語音
            playChinese(card.zh, {
              onEnd: () => {
                if (!isAutoPlaying || autoPlayToken !== currentToken) return;
                playSentenceStep();
              },
              onError: failAudio
            });
          }

          function playSentenceStep() {
            const example = card.example;
            if (example) {
              autoPlayStepTimer = setTimeout(() => {
                if (!isAutoPlaying || autoPlayToken !== currentToken) return;

                playSentence(example, false, {
                  onEnd: () => {
                    if (!isAutoPlaying || autoPlayToken !== currentToken) return;
                    proceedToNextCard(1000);
                  },
                  onError: failAudio
                });
              }, 500);
            } else {
              proceedToNextCard(800);
            }
          }
        }, thinkDelay);
      },
      onError: failAudio
    });
  }

  function proceedToNextCard(delay = 1000) {
    if (!isAutoPlaying || autoPlayToken !== currentToken) return;
    const batchCards = getBatchCards();

    // 依模式保留停頓時間，進行深度記憶沉澱
    autoPlayStepTimer = setTimeout(() => {
      if (!isAutoPlaying || autoPlayToken !== currentToken) return;

      if (currentCardIndex < batchCards.length - 1) {
        currentCardIndex++;
        runCurrentCard();
      } else {
        // 完成當前組練習！
        batchCompleted = true;
        isAutoPlaying = false;
        renderCallback();
      }
    }, delay);
  }

  runCurrentCard();
}

export function handleFlashcardInput(target, renderCallback) {
  if (target && target.id === 'fc-search-input') {
    const caret = target.selectionStart;
    cardSearchKeyword = target.value;
    currentBatchIndex = 0;
    currentCardIndex = 0;
    batchCompleted = false;
    isFlipped = false;
    stopFlashcardAutoPlay();
    renderCallback();
    const input = document.querySelector('#fc-search-input');
    input?.focus();
    if (caret !== null) input?.setSelectionRange(caret, caret);
    return true;
  }
  return false;
}
